package com.akashrajeev.voicebeam
import android.media.MediaExtractor
import android.media.MediaFormat
import androidx.test.platform.app.InstrumentationRegistry
import com.akashrajeev.voicebeam.separation.VideoAudioDecoder
import org.junit.Assert.*
import org.junit.Test
import java.io.File

/** ffmpeg edit-list fixtures, not MediaMuxer-generated offsets. */
class OffsetContainerTest {
    private fun file(name:String):File {
        val bytes=android.util.Base64.decode(fixtures.getValue(name),android.util.Base64.DEFAULT)
        val actual=java.security.MessageDigest.getInstance("SHA-256").digest(bytes).joinToString(""){"%02x".format(it)}
        assertEquals(hashes.getValue(name),actual)
        return File(InstrumentationRegistry.getInstrumentation().targetContext.cacheDir,name).also{it.writeBytes(bytes)}
    }
    private fun firstAudio(f:File):Long {
        val e=MediaExtractor();try{e.setDataSource(f.absolutePath)
            val index=(0 until e.trackCount).first{e.getTrackFormat(it).getString(MediaFormat.KEY_MIME)!!.startsWith("audio/")}
            e.selectTrack(index);return e.sampleTime
        }finally{e.release()}
    }
    private fun burst(name:String,expected:Double,late:Boolean=false,early:Boolean=false){
        val f=file(name);try{
            val pts=firstAudio(f)
            android.util.Log.i("OffsetFixture","$name firstAudioUs=$pts")
            if(early)assertTrue("Early edit-list start expected <=0, got $pts",pts<=0)
            val audio=VideoAudioDecoder.decode(f)
            val threshold=.04;val onset=audio.indices.firstOrNull{ i -> i+160<=audio.size && kotlin.math.sqrt((i until i+160).sumOf{audio[it].toDouble()*audio[it]}/160)>threshold } ?: error("Burst missing")
            val time=onset/16000.0
            android.util.Log.i("OffsetFixture","$name onset=$time expected=$expected samples=${audio.size}")
            assertEquals("Burst on video timeline",expected,time,.030)
            if(late)assertTrue("Late container offset must survive Android extraction, got $pts",kotlin.math.abs(pts-236000L)<2000L)
        }finally{f.delete()}
    }
    @Test fun alignedBurstAtOneSecond(){burst("fx_audio_aligned.mp4",1.0)}
    @Test fun lateBurstAtOnePointThree(){burst("fx_audio_late_0.3s.mp4",1.3,late=true)}
    @Test fun earlyBurstAtZeroPointEight(){burst("fx_audio_early_0.2s.mp4",.8,early=true)}
    @Test fun overCapRejectedByDecoder(){val f=file("fx_audio_late_2.3s.mp4");try{
        val pts=firstAudio(f);android.util.Log.i("OffsetFixture","cap firstAudioUs=$pts")
        try{val decoded=VideoAudioDecoder.decode(f); val onset=decoded.indices.firstOrNull{ i -> i+160<=decoded.size && kotlin.math.sqrt((i until i+160).sumOf{decoded[it].toDouble()*decoded[it]}/160)>.04 } ?: -1; android.util.Log.i("OffsetFixture","cap decoded onset=${onset/16000.0} samples=${decoded.size}");fail("Expected unsupported offset")}catch(e:IllegalArgumentException){assertTrue(e.message.orEmpty().contains("offset is unsupported"))}
    }finally{f.delete()}}
    private val fixtures=mapOf(
        "fx_audio_aligned.mp4" to "",
        "fx_audio_early_0.2s.mp4" to "",
        "fx_audio_late_0.3s.mp4" to "",
        "fx_audio_late_2.3s.mp4" to "")
    private val hashes=mapOf(
        "fx_audio_aligned.mp4" to "10576a14c59b79e479d1845311c66f5c2b8dfd5f8b358209c479bef7bd2aa319",
        "fx_audio_early_0.2s.mp4" to "20db8c385a32e9963573c55cba4cbccc0af29321c6aab438b5465764edca6ce0",
        "fx_audio_late_0.3s.mp4" to "f31feec9193c53469a8eb9c159c10e2f380e60fbce1932aab30b5f386e6def30",
        "fx_audio_late_2.3s.mp4" to "f8d9f0471126454f811c355d0ecbaeac4467297d5aed101b31fe65a8d83be5fc")
}
